   var texture=Texture.Load(texturePath);Assert.IsTrue(texture is {IsValid:true,IsError:false} && texture.Depth==6 && texture.Width==texture.Height && texture.Mips>1,"Expected verified native HDR cubemap");capture.View(new Vector3(-20.13f,-12.29f,5.10f),new Vector3(-1.65f,-5.55f,1.52f),27.2f);
