   using(capture.Scene.Push()){renderer=capture.Scene.CreateObject().Components.Create<ModelRenderer>(false);renderer.Model=model;renderer.Enabled=true;capture.Scene.EditorTick(0,0);}var warmInstance=renderer.GltfInstance;Assert.IsNotNull(warmInstance);var warmObject=warmInstance.SceneObject;await capture.Settle();var warmup=await capture.Take("warmup_real_model");Assert.IsTrue(warmInstance.DrawCalls>0,"Warmup did not submit the model");var warmBackground=warmup.Pixels[0];int warmupChanged=warmup.Pixels.Count(a=>Math.Abs(a.r-warmBackground.r)>.01f||Math.Abs(a.g-warmBackground.g)>.01f||Math.Abs(a.b-warmBackground.b)>.01f);Assert.IsTrue(warmupChanged>1000,"Actual warmup model is not visible against its background");using(capture.Scene.Push()){renderer.GameObject.Destroy();capture.Scene.EditorTick(0,0);capture.Scene.ProcessDeletes();}renderer=null;Assert.IsFalse(warmObject.IsValid(),"Warmup scene object survived deletion");int warmCalls=warmInstance.DrawCalls;await capture.Settle();var empty=await capture.Take("empty_no_model");Assert.AreEqual(warmCalls,warmInstance.DrawCalls,"Deleted warmup callback continued drawing");int initialNonuniform=Nonuniform(empty.Pixels);Assert.IsTrue(initialNonuniform<100,"Initial no-model frame is not uniform");probe.Delete();probe=null;
   using(capture.Scene.Push()){renderer=capture.Scene.CreateObject().Components.Create<ModelRenderer>(false);renderer.Model=model;renderer.Enabled=true;capture.Scene.EditorTick(0,0);}var instance=renderer.GltfInstance;Assert.IsNotNull(instance);Assert.IsTrue(renderer.SceneObject is SceneCustomObject && renderer.SceneObject.Model is null);await capture.Settle();var noProbe=await capture.Take("model_without_environment");
   probe=new SceneCubemap(capture.Scene.SceneWorld,texture,BBox.FromPositionAndSize(Vector3.Zero,1000));probe.Projection=SceneCubemap.ProjectionMode.Sphere;probe.Transform=Transform.Zero.WithRotation(Rotation.FromYaw(yaw));probe.TintColor=Color.White;probe.Feathering=.01f;probe.RenderDirty();Assert.IsTrue(probe.IsValid());await capture.Settle();var withProbe=await capture.Take("model_with_hdr_environment");int changed=noProbe.Pixels.Zip(withProbe.Pixels,(a,b)=>Math.Abs(a.r-b.r)>.01f||Math.Abs(a.g-b.g)>.01f||Math.Abs(a.b-b.b)>.01f).Count(x=>x);Assert.IsTrue(changed>1000,"Actual environment must materially change public model pixels");Assert.AreEqual(0,instance.CallbackErrors.Length);Assert.IsTrue(instance.DrawCalls>0);var exposureState=capture.VerifyExposure();capture.SetExposure(0);await capture.Settle();var exposureZero=await capture.Take("exposure_zero_negative");capture.SetExposure(2);await capture.Settle();var exposureTwo=await capture.Take("exposure_two_positive");int exposureChanged=exposureZero.Pixels.Zip(exposureTwo.Pixels,(a,b)=>Math.Abs(a.r-b.r)>.01f||Math.Abs(a.g-b.g)>.01f||Math.Abs(a.b-b.b)>.01f).Count(x=>x);
   var noProbeBackground=noProbe.Pixels[0];var foreground=noProbe.Pixels.Select(a=>Math.Abs(a.r-noProbeBackground.r)>.01f||Math.Abs(a.g-noProbeBackground.g)>.01f||Math.Abs(a.b-noProbeBackground.b)>.01f).ToArray();int foregroundCount=foreground.Count(x=>x);Assert.IsTrue(foregroundCount>1000,"Foreground control missing");int environmentForeground=Enumerable.Range(0,foreground.Length).Count(i=>foreground[i]&&(Math.Abs(noProbe.Pixels[i].r-withProbe.Pixels[i].r)>.01f||Math.Abs(noProbe.Pixels[i].g-withProbe.Pixels[i].g)>.01f||Math.Abs(noProbe.Pixels[i].b-withProbe.Pixels[i].b)>.01f));Assert.IsTrue(environmentForeground>1000,"HDR probe did not affect model foreground pixels");int exposureForeground=Enumerable.Range(0,foreground.Length).Count(i=>foreground[i]&&(Math.Abs(exposureZero.Pixels[i].r-exposureTwo.Pixels[i].r)>.01f||Math.Abs(exposureZero.Pixels[i].g-exposureTwo.Pixels[i].g)>.01f||Math.Abs(exposureZero.Pixels[i].b-exposureTwo.Pixels[i].b)>.01f));
   var images=new List<object>();foreach(float angle in new[]{0f,90f,180f,270f}){probe.Transform=Transform.Zero.WithRotation(Rotation.FromYaw(angle));probe.RenderDirty();await capture.Settle();var frame=await capture.Take("candidate_yaw_"+angle);images.Add(new{yaw=angle,path=frame.Path,sha256=frame.Sha,width=800,height=620});}
   probe.Transform=Transform.Zero.WithRotation(Rotation.FromYaw(0));probe.RenderDirty();capture.SetExposure(1);await capture.Settle();var evOne=await capture.Take("exposure_one_diagnostic");capture.SetExposure(2);await capture.Settle();var final=await capture.Take("canonical_reference_candidate");

   Measurements.Add(new{input_sha256=Hash(compiled),environment_texture=texturePath,source_sha256=Hash(File.ReadAllBytes(sourcePath)),compiled_environment_sha256=Hash(File.ReadAllBytes(compiledPath)),environment_yaw=yaw,texture.Width,texture.Height,texture.Depth,texture.Mips,environment_changed_pixels=changed,environment_foreground_changed_pixels=environmentForeground,exposure_changed_pixels=exposureChanged,exposure_foreground_changed_pixels=exposureForeground,foreground_pixels=foregroundCount,warmup_changed_pixels=warmupChanged,initial_empty_nonuniform_pixels=initialNonuniform,initial_empty_color=empty.Pixels[0].ToString(),warmup_model_path=warmup.Path,warmup_model_sha256=warmup.Sha,exposure_one_path=evOne.Path,exposure_one_sha256=evOne.Sha,final_path=final.Path,final_sha256=final.Sha,exposure_zero_path=exposureZero.Path,exposure_zero_sha256=exposureZero.Sha,exposure_two_path=exposureTwo.Path,exposure_two_sha256=exposureTwo.Sha,no_environment_path=noProbe.Path,empty_path=empty.Path,images,exposure_min=1,exposure_max=1,exposure_compensation_ev=2,exposure_observed=exposureState,tonemap="ACES",background="constant warm-neutral, not original backdrop",scope="Actual public canonical Model.Load/ModelRenderer and native scene cubemap. Camera fit is approximate; asset HDRI named in reference, yaw candidates and engine ACES/exposure equivalence need visual review. Optical extensions remain core fallback."});
   var actualObject=instance.SceneObject;using(capture.Scene.Push()){renderer.GameObject.Destroy();capture.Scene.EditorTick(0,0);capture.Scene.ProcessDeletes();}renderer=null;Assert.IsFalse(actualObject.IsValid(),"Public scene object survived deletion");int finalCalls=instance.DrawCalls;var after=await capture.Take("empty_after_delete");Assert.AreEqual(finalCalls,instance.DrawCalls,"Deleted public callback continued drawing");int finalNonuniform=Nonuniform(after.Pixels);Measurements.Add(new{phase="deletion_control",path=after.Path,sha256=after.Sha,nonuniform_pixels=finalNonuniform,color=after.Pixels[0].ToString(),scene_object_invalid=true,draw_calls_stopped=true});Assert.IsTrue(finalNonuniform<100,"Post-deletion frame is not an independently uniform background");Assert.IsTrue(exposureForeground>1000,"+2 EV was configured but did not measurably alter model foreground pixels");
  }
  finally{await MainThread.Wait();try{if(renderer!=null){using var scope=capture.Scene.Push();renderer.GameObject.Destroy();capture.Scene.EditorTick(0,0);capture.Scene.ProcessDeletes();}if(probe.IsValid())probe.Delete();model?.Destroy();}finally{try{if(mount!=null)FileSystem.Mounted.UnMount(mount);}finally{mount?.Dispose();Directory.Delete(dir,true);}}}
 }
 static int Nonuniform(Color[] pixels){var b=pixels[0];return pixels.Count(a=>Math.Abs(a.r-b.r)>.01f||Math.Abs(a.g-b.g)>.01f||Math.Abs(a.b-b.b)>.01f);}
 static string Hash(byte[] b)=>Convert.ToHexStringLower(SHA256.HashData(b));
 sealed class Capture:IDisposable
 {
  public record Frame(Color[] Pixels,string Path,string Sha);public readonly Scene Scene;readonly CameraComponent camera;readonly Tonemapping tone;readonly Editor.SceneRenderingWidget widget;readonly string output;readonly Action onFrame;int frames;
  public Capture(string path){output=path;Scene=Scene.CreateEditorScene();using(Scene.Push()){camera=Scene.CreateObject().Components.Create<CameraComponent>();camera.Orthographic=false;camera.FovAxis=CameraComponent.Axis.Vertical;camera.ZNear=.1f;camera.ZFar=1000;camera.CustomSize=new Vector2(800,620);camera.BackgroundColor=new Color(.65f,.62f,.58f,1);camera.ClearFlags=ClearFlags.All;camera.EnablePostProcessing=true;camera.DebugMode=SceneCameraDebugMode.Normal;tone=camera.GameObject.Components.Create<Tonemapping>();tone.Mode=Tonemapping.TonemappingMode.ACES;tone.AutoExposureEnabled=true;tone.MinimumExposure=1;tone.MaximumExposure=1;tone.ExposureCompensation=2;Scene.EditorTick(0,0);}widget=new Editor.SceneRenderingWidget{Scene=Scene,Camera=camera,WindowTitle="A Beautiful Game reference reconstruction",Size=new Vector2(800,620)};onFrame=()=>frames++;widget.OnPreFrame+=onFrame;widget.Show();}
  public void SetExposure(float value){using(Scene.Push()){tone.ExposureCompensation=value;Scene.EditorTick(0,0);}}
  public object VerifyExposure(){var e=camera.AutoExposure;Assert.IsTrue(e.Enabled && Math.Abs(e.MinimumExposure-1)<.0001f && Math.Abs(e.MaximumExposure-1)<.0001f && Math.Abs(e.Compensation-2)<.0001f,"ACES exposure settings were overwritten at render time");return new{e.Enabled,e.MinimumExposure,e.MaximumExposure,e.Compensation,e.Rate,scope="Camera settings observed after render; not photometric proof of Babylon tone-curve equivalence"};}
  public void View(Vector3 pos,Vector3 target,float fov){using(Scene.Push()){camera.WorldPosition=pos;camera.WorldRotation=Rotation.LookAt(target-pos,Vector3.Up);camera.FieldOfView=fov;Scene.EditorTick(0,0);}}
  async Task Wait(){await MainThread.Wait();var start=frames;var timer=Stopwatch.StartNew();while(frames<start+3||Graphics.IsActive){Assert.IsTrue(timer.Elapsed<TimeSpan.FromSeconds(15),"Preview frames stalled");await Task.Delay(20);await MainThread.Wait();}}
  public async Task Settle(){for(int i=0;i<20;i++)await Wait();}
  public async Task<Frame> Take(string name){await Wait();using(Scene.Push()){Scene.PreCameraRender();camera.InitializeRendering(false);}using var target=Texture.CreateRenderTarget().WithSize(800,620).WithFormat(ImageFormat.RGBA8888).WithInitialColor(Color.Magenta).Create("beautiful_reference_"+Guid.NewGuid().ToString("N"));bool ok;using(Scene.Push()){target.Clear(Color.Magenta);ok=camera.RenderToTexture(target);}Assert.IsTrue(ok);await Wait();using var bitmap=target.GetBitmap();var pixels=bitmap.GetPixels();Assert.AreEqual(800*620,pixels.Length);byte[] png=bitmap.ToPng();string path=Path.Combine(output,name+".png");File.WriteAllBytes(path,png);return new(pixels,path,Hash(png));}
  public void Dispose(){if(widget.IsValid){widget.OnPreFrame-=onFrame;widget.Close();widget.Destroy();}Scene.Destroy();}
 }
